 r(r'\mathcal O_V',r'\text{\uwave{O}}_V','Picard tangent structure sheaves',count=3,why='All three O letters have wavy underlines.')
 r(r'\subsection*{2. Schémas $\underline{\operatorname{Hom}}_S(X,Y)$,'+'\n'+r'$\Pi_{X/S}Z$, $\underline{\operatorname{Aut}}_S(X)$, etc.}',r'\subsection*{\normalfont 2. \uline{Schémas} $\text{\uwave{Hom}}_S(X,Y)$,'+'\n'+r'$\Pi_{X/S}Z$, $\text{\uwave{Aut}}_S(X)$ etc.}','section 2 heading',why='Roman heading, Schémas underlined, Hom and Aut with wavy underlines, and no comma before etc.')
 if tree=='fr_printed':
  r(r'\text{\uwave{O}}_Y',r'\text{\uwave{O}}_X','opening sheaf subscript',why='The scan prints X although the varying test scheme has just been named Y.')
